def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        if maxsize is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif typed is None:
            def wrapper(*args, **kwargs):
                try:
                    return cache[key(*args, **kwargs)]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[key(*args, **kwargs)] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
