def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Check if path is a valid directory
    if not os.path.isdir(path):
        raise errors.NotADirectoryError(f"Path {path} is not a valid directory")

    # Check if path contains an OCFL object root
    if not os.path.exists(os.path.join(path, "ocfl_root.json")):
        raise errors.InvalidOCFLObjectError(f"Path {path} does not contain an OCFL object root")

    # Check if OCFL object root is valid
    with open(os.path.join(path, "ocfl_root.json"), "r") as f:
        try:
            ocfl_root = json.load(f)
        except json.JSONDecodeError:
            raise errors.InvalidOCFLObjectError(f"OCFL object root at {path} is not valid JSON")
        if not isinstance(ocfl_root, dict):
            raise errors.InvalidOCFLObjectError(f"OCFL object root at {path} is not a JSON object")
        if "id" not in ocfl_root:
            raise errors.InvalidOCFLObjectError(f"OCFL object root at {path} does not contain an 'id' field")
        if "type" not in ocfl_root:
            raise errors.InvalidOCFLObjectError(f"OCFL object root at {path} does not contain a 'type' field")
        if ocfl_root["type"] != "https://ocfl.io/1.0/spec/#object":
            raise errors.InvalidOCFLObjectError(f"OCFL object root at {path} has an invalid 'type' field")

    # Check if OCFL object contains a version directory
    version_dirs = [d for d in os.listdir(path) if os.path.isdir(os.path.join(path, d)) and d.startswith("v")]
    if not version_dirs:
        raise errors.InvalidOCFLObjectError(f"OCFL object at {path} does not contain any version directories")

    # Check if each version directory is valid
    for version_dir in version_dirs:
        version_path = os.path.join(path, version_dir)
        if not os.path.exists(os.path.join(version_path, "inventory.json")):
            raise errors.InvalidOCFLVersionError(f"Version directory {version_dir} does not contain an inventory.json file")
        with open(os.path.join(version_path, "inventory.json"), "r") as f:
            try:
                inventory = json.load(f)
            except json.JSONDecodeError:
                raise errors.InvalidOCFLVersionError(f"Inventory file for version {version_dir} is not valid JSON")
            if not isinstance(inventory, dict):
