def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    for command in commands:
        if not isinstance(command, str):
            raise ValueError("command must be a string")
        if not isinstance(args, list):
            raise ValueError("args must be a list")
        if cwd and not isinstance(cwd, str):
            raise ValueError("cwd must be a string")
        if env and not isinstance(env, dict):
            raise ValueError("env must be a dictionary")
        try:
            subprocess.check_call(command, args, cwd=cwd, env=env,
                                  stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE)
        except subprocess.CalledProcessError as e:
            if hide_stderr:
                print(e.output.decode("utf-8"), end="")
            else:
                print(e.output.decode("utf-8"), file=sys.stderr, end="")
            if verbose:
                print("Command '{}' failed with exit code {}".format(
                    command, e.returncode), file=sys.stderr)
            return e.returncode
        except OSError as e:
            if e.errno == errno.ENOENT:
                print("Command '{}' not found".format(command), file=sys.stderr)
            else:
                print("Error running command '{}': {}".format(
                    command, e.strerror), file=sys.stderr)
            return 1
    return 0

