def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        data = json.loads(document)
        return {
            "subject": data["subject"],
            "aliases": data["aliases"],
            "links": data["links"],
        }
    except json.JSONDecodeError:
        pass

    try:
        xrd = XRD.parse(document)
        return {
            "subject": xrd.subject,
            "aliases": [link.href for link in xrd.links if link.rel == "http://schemas.google.com/g/2010#updates-from"],
            "links": [link.href for link in xrd.links],
        }
    except XRDError:
        pass

    return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
        document, code, exception = fetch_document(
            host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
        )
        if document:
            return document
        hostmeta = retrieve_diaspora_host_meta(host)
        if not hostmeta:
            return None
        url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
        document, code, exception = fetch_document(url)
        if exception:
            return None
        return document
    except Exception as e:
        logger.warning("try_retrieve_webfinger_document: failed to retrieve webfinger document for handle %s: %s", handle, e)
        return None

