def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if any deprecated arguments are used
    deprecated_args = self.parsed_yaml.get('deprecated_args', {})
    for arg, new_arg in deprecated_args.items():
        if arg in cli_args or arg in answer_file_args:
            warnings.warn(
                "Keyword argument '{}' has been deprecated in favour of '{}'. '{}' will be removed in a future version."
                .format(arg, new_arg, arg),
                category=DeprecationWarning,
                stacklevel=2,
            )

    # Check if any new arguments are used
    new_args = self.parsed_yaml.get('new_args', {})
    for arg, old_arg in new_args.items():
        if arg in cli_args or arg in answer_file_args:
            warnings.warn(
                "Keyword argument '{}' has been added as a replacement for '{}'. '{}' will be removed in a future version."
                .format(arg, old_arg, old_arg),
                category=DeprecationWarning,
                stacklevel=2,
            )

    # Check if any arguments are used that are not in the current version
    current_args = self.parsed_yaml.get('current_args', {})
    for arg in cli_args:
        if arg not in current_args:
            warnings.warn(
                "Keyword argument '{}' is not recognized. It will be ignored.".format(arg),
                category=DeprecationWarning,
                stacklevel=2,
            )

    for arg in answer_file_args:
        if arg not in current_args:
            warnings.warn(
                "Keyword argument '{}' is not recognized. It will be ignored.".format(arg),
                category=DeprecationWarning,
                stacklevel=2,
            )

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    for arg in self.args:
        if arg.required and arg.name not in args:
            raise ValueError(f"Missing required argument: {arg.name}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        if option.get('required_when'):
            condition = option['required_when']
            if isinstance(condition, str):
                condition = [condition]
            for c in condition:
                if c in args:
                    required_args.append(option['name'])
                    break
    return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg in args:
        if len(arg) > self.length:
            raise ValueError(f"Argument {arg} is longer than the allowed length of {self.length}")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg.choices and arg.value not in arg.choices:
            raise ValueError(f"Invalid choice: {arg.value}. Must be one of {arg.choices}")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for k, v in args.items():
        if k.startswith('control_'):
            control_args[k] = v
        elif k.startswith('nested_'):
            nested_args[k] = v
        else:
            custom_args[k] = v

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for key, value in extra_vars.items():
        if key not in vars_dict:
            vars_dict[key] = value
        else:
            vars_dict[key] = merge_extra_vars(vars_dict[key], value)
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    plugin_spec = load_plugin_spec(plugin_dir)
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value
    return flatten_dict
